 1	import { beforeEach, describe, expect, it } from 'vitest';
 2	import { prisma } from '../src/db/client.js';
 3	import { resetDb } from './helpers/app.js';
 4	
 5	describe('database schema', () => {
 6	  beforeEach(async () => {
 7	    await resetDb();
 8	  });
 9	
10	  it('stores a room and reads it back', async () => {
11	    const room = await prisma.room.create({ data: { name: 'Aurora', capacity: 8 } });
12	    const found = await prisma.room.findUnique({ where: { id: room.id } });
13	    expect(found?.name).toBe('Aurora');
14	  });
15	
16	  it('defaults a booking to the active status', async () => {
17	    const room = await prisma.room.create({ data: { name: 'Borealis', capacity: 4 } });
18	    const user = await prisma.user.create({ data: { name: 'Ada', email: 'ada@example.com' } });
19	    const booking = await prisma.booking.create({
20	      data: {
21	        roomId: room.id,
22	        userId: user.id,
23	        title: 'Sync',
24	        startsAt: new Date(Date.now() + 3_600_000),
25	        endsAt: new Date(Date.now() + 7_200_000),
26	      },
27	    });
28	    expect(booking.status).toBe('ACTIVE');
29	  });
30	
31	  it('rejects a booking that points at a room that does not exist', async () => {
32	    const user = await prisma.user.create({ data: { name: 'Grace', email: 'grace@example.com' } });
33	    await expect(
34	      prisma.booking.create({
35	        data: {
36	          roomId: 'missing-room',
37	          userId: user.id,
38	          title: 'Sync',
39	          startsAt: new Date(Date.now() + 3_600_000),
40	          endsAt: new Date(Date.now() + 7_200_000),
41	        },
42	      }),
43	    ).rejects.toThrow();
44	  });
45	});

