import re
p = 'src/modules/bookings/schema.ts'
s = open(p).read()

s = s.replace(
"""export const BOOKING_ACTIVE = 'ACTIVE';
export const BOOKING_CANCELLED = 'CANCELLED';
""",
"""export const BOOKING_ACTIVE = 'ACTIVE';
export const BOOKING_CANCELLED = 'CANCELLED';

export const MIN_BOOKING_MINUTES = 30;
export const MAX_BOOKING_MINUTES = 480;
""")

s = s.replace(
"""export type CreateBookingInput = Static<typeof CreateBookingBody>;""",
"""export const AvailabilityQuery = Type.Object({
  roomId: Type.String({ minLength: 1 }),
  from: Type.String({ minLength: 1 }),
  to: Type.String({ minLength: 1 }),
  durationMinutes: Type.Optional(Type.Integer({ minimum: 1 })),
});

export const AvailabilityResponse = Type.Object({
  roomId: Type.String(),
  from: DateString,
  to: DateString,
  slots: Type.Array(
    Type.Object({
      startsAt: DateString,
      endsAt: DateString,
    }),
  ),
});

export type CreateBookingInput = Static<typeof CreateBookingBody>;""")

s = s.replace(
"""export type ListBookingsInput = Static<typeof ListBookingsQuery>;""",
"""export type ListBookingsInput = Static<typeof ListBookingsQuery>;
export type AvailabilityInput = Static<typeof AvailabilityQuery>;""")

open(p,'w').write(s)
