}

function assertWindow(startsAt: Date, endsAt: Date): void {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('Booking must end after it starts');
  }
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('Booking cannot start in the past');
  }
  const span = endsAt.getTime() - startsAt.getTime();
  if (span < MIN_BOOKING_MINUTES * MINUTE_IN_MS || span > MAX_BOOKING_MINUTES * MINUTE_IN_MS) {
    throw validationFailed('Booking duration is out of range', {
      durationMinutes: durationMinutes(startsAt, endsAt),
      minMinutes: MIN_BOOKING_MINUTES,
      maxMinutes: MAX_BOOKING_MINUTES,
    });
  }
}

async function assertRoomExists(roomId: string): Promise<void> {
  if (!(await repository.findRoomById(roomId))) {
    throw notFound('Room');
  }
}

async function assertUserExists(userId: string): Promise<void> {
  if (!(await repository.findUserById(userId))) {
    throw notFound('User');
  }
}

async function assertNoConflict(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Promise<void> {
  const conflict = await repository.findConflict(roomId, startsAt, endsAt, excludeId);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);

  assertWindow(startsAt, endsAt);
  await assertRoomExists(input.roomId);
  await assertUserExists(input.userId);
  await assertNoConflict(input.roomId, startsAt, endsAt);

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function listAvailableSlots(query: AvailabilityInput): Promise<Availability> {
  const from = parseInstant(query.from);
  const to = parseInstant(query.to);
  if (!isBefore(from, to)) {
    throw validationFailed('Availability window must end after it starts');
  }
  await assertRoomExists(query.roomId);

  // A booking never starts in the past, so a slot that has already begun is of
  // no use to whoever is asking: the window effectively starts at the later of
  // the requested start and now, and the answer reports that effective window.
  const now = new Date();
  const start = isBefore(from, now) ? now : from;

  const bookings = await repository.listActiveBetween(query.roomId, from, to);
  const slots: Slot[] = [];
  let cursor = start;
  for (const booking of bookings) {
    if (isBefore(cursor, booking.startsAt)) {
      slots.push({ startsAt: cursor, endsAt: booking.startsAt });
    }
    if (isBefore(cursor, booking.endsAt)) {
      cursor = booking.endsAt;
    }
  }
  if (isBefore(cursor, to)) {
    slots.push({ startsAt: cursor, endsAt: to });
  }

  const minimum = query.durationMinutes;
  return {
    roomId: query.roomId,
    from: start,
    to,
    slots:
      minimum === undefined
        ? slots
        : slots.filter(
            (slot) => slot.endsAt.getTime() - slot.startsAt.getTime() >= minimum * MINUTE_IN_MS,
          ),
  };
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const current = await getBooking(id);

  const roomId = input.roomId ?? current.roomId;
  const startsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : current.startsAt;
  const endsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : current.endsAt;

  if (input.roomId !== undefined) {
    await assertRoomExists(roomId);
  }
  if (input.userId !== undefined) {
    await assertUserExists(input.userId);
  }
  // Moving the room or the schedule has to obey the same rules as creating the
  // booking, measured against the booking as it will be once the patch lands.
  if (input.roomId !== undefined || input.startsAt !== undefined || input.endsAt !== undefined) {
    assertWindow(startsAt, endsAt);
    await assertNoConflict(roomId, startsAt, endsAt, id);
  }

  return repository.update(id, {
    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt } : {}),
    ...(input.endsAt !== undefined ? { endsAt } : {}),
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}
